-- Piezas que el equipo ajusta después de crearlas (p. ej. bajar de Java 25 / Spring Boot 4 a Java 21 / Spring Boot 3):
-- notas para los agentes. Y plantillas nuevas: API Spring Boot 3 con Java 21 y monolitos de varias tecnologías, que llegan
-- a los espacios como entradas nuevas del catálogo de la plataforma.

alter table project_component add column notes text;

create temporary table new_catalog (type varchar(20), entry_key varchar(40), payload text) on commit drop;
