-- Solo si el catálogo de la plataforma ya existe (uno nuevo se siembra del YAML) y sin pisar una entrada con la misma clave.
insert into platform_catalog_entry (type, entry_key, payload, published_payload, updated_at)
select n.type, n.entry_key, n.payload, n.payload, now()
from new_catalog n
where exists (select 1 from platform_catalog_release)
  and not exists (select 1 from platform_catalog_entry p where p.type = n.type and p.entry_key = n.entry_key);

insert into platform_catalog_release (version, added, updated, published_at)
select coalesce(max(version), 0) + 1, '[{"type":"COMPONENT_TEMPLATE","key":"API_SPRING_3"},{"type":"COMPONENT_TEMPLATE","key":"MONOLITH_SPRING"},{"type":"COMPONENT_TEMPLATE","key":"MONOLITH_DOTNET"},{"type":"COMPONENT_TEMPLATE","key":"MONOLITH_LARAVEL"},{"type":"COMPONENT_TEMPLATE","key":"MONOLITH_DJANGO"},{"type":"COMPONENT_TEMPLATE","key":"MONOLITH_RAILS"},{"type":"COMPONENT_TEMPLATE","key":"MONOLITH_NEXTJS"}]', '[]', now()
from platform_catalog_release
having exists (select 1 from platform_catalog_release);
